private val dateFmt=DateTimeFormatter.ofPattern("dd/MM/yyyy")
private fun money(cents:Long)=NumberFormat.getCurrencyInstance().format(cents/100.0)
private fun date(ms:Long)=Instant.ofEpochMilli(ms).atZone(ZoneId.systemDefault()).toLocalDate().format(dateFmt)
private fun parseDate(v:String)=runCatching{LocalDate.parse(v,dateFmt).atStartOfDay(ZoneId.systemDefault()).toInstant().toEpochMilli()}.getOrNull()

@Composable fun WarrantyBoxRoot(vm:MainViewModel,dark:Boolean,onDark:(Boolean)->Unit,activity:FragmentActivity){
 val nav=rememberNavController(); val products by vm.products.collectAsState(); val prefs=remember{activity.getSharedPreferences("settings",Context.MODE_PRIVATE)}
 val security=remember{SecurityManager(activity)};var unlocked by remember{mutableStateOf(!security.lockEnabled)}
 if(!unlocked){LockScreen(security,activity){unlocked=true};return}
 Scaffold(bottomBar={NavigationBar{listOf("home" to Icons.Default.Home,"products" to Icons.Default.Inventory2,"add" to Icons.Default.AddCircle,"stats" to Icons.Default.BarChart,"settings" to Icons.Default.Settings).forEach{(r,i)->NavigationBarItem(selected=nav.currentBackStackEntryAsState().value?.destination?.route==r,onClick={nav.navigate(r){popUpTo("home");launchSingleTop=true}},icon={Icon(i,null)},label={Text(when(r){"home"->stringResource(R.string.home);"products"->stringResource(R.string.products);"add"->stringResource(R.string.add);"stats"->stringResource(R.string.statistics);else->stringResource(R.string.settings)})})}}},floatingActionButton={if(nav.currentBackStackEntryAsState().value?.destination?.route=="home")FloatingActionButton({nav.navigate("add")}){Icon(Icons.Default.Add,null)}}){pad->
  NavHost(nav,"home",Modifier.padding(pad)){composable("home"){Dashboard(products,{nav.navigate("detail/$it")})};composable("products"){ProductsScreen(products,{nav.navigate("detail/$it")})};composable("add"){ProductForm(vm,null,{nav.popBackStack()})};composable("edit/{id}"){b->ProductForm(vm,b.arguments?.getString("id")?.toLong(),{nav.popBackStack()})};composable("detail/{id}"){b->DetailScreen(vm,b.arguments?.getString("id")!!.toLong(),nav)};composable("problem/{id}"){b->ProblemScreen(vm,b.arguments?.getString("id")!!.toLong())};composable("stats"){StatsScreen(vm)};composable("settings"){SettingsScreen(vm,dark,onDark,prefs,activity)}}
 }
}

@Composable private fun LockScreen(security:SecurityManager,activity:FragmentActivity,unlocked:()->Unit){
 var pin by remember{mutableStateOf("")};var error by remember{mutableStateOf(false)}
 fun biometric(){val prompt=BiometricPrompt(activity,object:BiometricPrompt.AuthenticationCallback(){override fun onAuthenticationSucceeded(r:BiometricPrompt.AuthenticationResult)=unlocked();override fun onAuthenticationError(c:Int,m:CharSequence){error=true}});prompt.authenticate(BiometricPrompt.PromptInfo.Builder().setTitle("WarrantyBox").setSubtitle(activity.getString(R.string.biometric_lock)).setNegativeButtonText(activity.getString(R.string.cancel)).build())}
 Box(Modifier.fillMaxSize().padding(24.dp),contentAlignment=Alignment.Center){Column(horizontalAlignment=Alignment.CenterHorizontally,verticalArrangement=Arrangement.spacedBy(16.dp)){Icon(Icons.Default.VerifiedUser,null,Modifier.size(72.dp),MaterialTheme.colorScheme.primary);Text("WarrantyBox",style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.Bold)
  if(security.hasPin){OutlinedTextField(pin,{pin=it.filter(Char::isDigit).take(6);error=false},label={Text("PIN")},visualTransformation=PasswordVisualTransformation(),keyboardOptions=KeyboardOptions(keyboardType=KeyboardType.NumberPassword),isError=error,supportingText=if(error){{Text("PIN incorreto")}}else null,singleLine=true);Button({if(security.verifyPin(pin))unlocked()else error=true},enabled=pin.length>=4){Text("Desbloquear")}}
  if(security.biometricEnabled)OutlinedButton(::biometric){Icon(Icons.Default.Fingerprint,null);Spacer(Modifier.width(8.dp));Text(stringResource(R.string.biometric_lock))}
 }}
}
@Composable private fun Dashboard(items:List<ProductWithDetails>,open:(Long)->Unit){val now=System.currentTimeMillis();val active=items.filter{it.product.warrantyEndDate>=now};val expiring=active.count{it.product.daysRemaining()<=90};LazyColumn(Modifier.fillMaxSize().padding(20.dp),verticalArrangement=Arrangement.spacedBy(16.dp)){item{Text("WarrantyBox",style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.Bold);Text(stringResource(R.string.tagline),color=MaterialTheme.colorScheme.onSurfaceVariant)};item{Row(horizontalArrangement=Arrangement.spacedBy(10.dp)){Metric(stringResource(R.string.active_warranties),active.size.toString(),Modifier.weight(1f));Metric(stringResource(R.string.expiring),expiring.toString(),Modifier.weight(1f))}};item{Metric(stringResource(R.string.protected_value),money(active.sumOf{it.product.priceCents}),Modifier.fillMaxWidth())};item{Text(stringResource(R.string.next_expirations),style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold)};items(active.sortedBy{it.product.warrantyEndDate}.take(5)){ProductCard(it,open)}}}
@Composable private fun Metric(title:String,value:String,mod:Modifier){Card(mod,shape=RoundedCornerShape(22.dp)){Column(Modifier.padding(18.dp)){Text(title,color=MaterialTheme.colorScheme.onSurfaceVariant);Text(value,style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold)}}}

@Composable private fun ProductsScreen(items:List<ProductWithDetails>,open:(Long)->Unit){
 var q by remember{mutableStateOf("")};var sort by remember{mutableStateOf("expiry")};var status by remember{mutableStateOf("all")};var categoryId by remember{mutableStateOf<Long?>(null)};var menu by remember{mutableStateOf(false)}
 val categories=items.mapNotNull{it.category}.distinctBy{it.id}.sortedBy{it.name}
 val filtered=items.filter{item->listOf(item.product.name,item.product.brand,item.product.model,item.product.store,item.product.serialNumber,item.product.orderNumber).any{it.contains(q,true)}}.filter{categoryId==null||it.product.categoryId==categoryId}.filter{when(status){"active"->it.product.daysRemaining()>90;"expiring"->it.product.daysRemaining() in 0..90;"expired"->it.product.daysRemaining()<0;else->true}}.let{l->when(sort){"value"->l.sortedByDescending{it.product.priceCents};"name"->l.sortedBy{it.product.name.lowercase()};"recent"->l.sortedByDescending{it.product.purchaseDate};else->l.sortedBy{it.product.warrantyEndDate}}}
 Column(Modifier.fillMaxSize().padding(16.dp)){Text(stringResource(R.string.products),style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.Bold);OutlinedTextField(q,{q=it},Modifier.fillMaxWidth().padding(vertical=10.dp),leadingIcon={Icon(Icons.Default.Search,null)},placeholder={Text(stringResource(R.string.search_hint))})
  LazyRow(horizontalArrangement=Arrangement.spacedBy(8.dp)){items(listOf("all" to "Todas","active" to "Ativas","expiring" to "A terminar","expired" to "Expiradas")){(k,v)->FilterChip(status==k,{status=k},{Text(v)})}}
  Box{OutlinedButton({menu=true}){Text(categories.firstOrNull{it.id==categoryId}?.name?:"Todas as categorias");Icon(Icons.Default.ArrowDropDown,null)};DropdownMenu(menu,{menu=false}){DropdownMenuItem({Text("Todas as categorias")},{categoryId=null;menu=false});categories.forEach{cat->DropdownMenuItem({Text(cat.name)},{categoryId=cat.id;menu=false})}}}
  LazyRow(horizontalArrangement=Arrangement.spacedBy(8.dp)){items(listOf("expiry" to "Fim","recent" to "Recente","value" to "Valor","name" to "Nome")){(k,v)->FilterChip(sort==k,{sort=k},{Text(v)})}}
  LazyColumn(verticalArrangement=Arrangement.spacedBy(10.dp),contentPadding=PaddingValues(vertical=12.dp)){if(filtered.isEmpty())item{Text(stringResource(R.string.no_products))};items(filtered,key={it.product.id}){ProductCard(it,open)}}
 }
}
@Composable private fun ProductCard(item:ProductWithDetails,open:(Long)->Unit){val p=item.product;Card(Modifier.fillMaxWidth().clickable{open(p.id)},shape=RoundedCornerShape(18.dp)){Row(Modifier.padding(14.dp),verticalAlignment=Alignment.CenterVertically){if(p.photoUri!=null)AsyncImage(Uri.parse(p.photoUri),null,Modifier.size(58.dp),contentScale=ContentScale.Crop)else Icon(Icons.Default.Inventory2,null,Modifier.size(48.dp),MaterialTheme.colorScheme.primary);Spacer(Modifier.width(14.dp));Column(Modifier.weight(1f)){Text(p.name,fontWeight=FontWeight.Bold);Text(listOf(p.brand,p.model).filter{it.isNotBlank()}.joinToString(" · "),color=MaterialTheme.colorScheme.onSurfaceVariant);StatusText(p)};Text(money(p.priceCents),fontWeight=FontWeight.SemiBold)}}}
@Composable private fun StatusText(p:ProductEntity){val d=p.daysRemaining();val c=if(d<0)MaterialTheme.colorScheme.error else if(d<=90)Color(0xFFB06000) else MaterialTheme.colorScheme.primary;Text(if(d<0)"Expirou há ${-d} dias" else "Termina dentro de $d dias",color=c,style=MaterialTheme.typography.bodySmall)}

@Composable private fun ProductForm(vm:MainViewModel,id:Long?,done:()->Unit){val existing=if(id!=null)vm.product(id).collectAsState(initial=null).value?.product else null;var name by remember(existing){mutableStateOf(existing?.name?:"")};var brand by remember(existing){mutableStateOf(existing?.brand?:"")};var model by remember(existing){mutableStateOf(existing?.model?:"")};var store by remember(existing){mutableStateOf(existing?.store?:"")};var price by remember(existing){mutableStateOf(existing?.let{(it.priceCents/100.0).toString()}?:"")};var purchase by remember(existing){mutableStateOf(existing?.let{date(it.purchaseDate)}?:date(System.currentTimeMillis()))};var months by remember(existing){mutableStateOf(existing?.warrantyMonths?.toString()?:"24")};var serial by remember(existing){mutableStateOf(existing?.serialNumber?:"")};var order by remember(existing){mutableStateOf(existing?.orderNumber?:"")};var notes by remember(existing){mutableStateOf(existing?.notes?:"")};var photo by remember(existing){mutableStateOf(existing?.photoUri)};var invoice by remember(existing){mutableStateOf(existing?.invoiceUri)};var attempted by remember{mutableStateOf(false)};val context=LocalContext.current;val photoPick=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()){it?.let{context.contentResolver.takePersistableUriPermission(it,Intent.FLAG_GRANT_READ_URI_PERMISSION);photo=it.toString()}};val invoicePick=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()){it?.let{context.contentResolver.takePersistableUriPermission(it,Intent.FLAG_GRANT_READ_URI_PERMISSION);invoice=it.toString()}};LazyColumn(Modifier.fillMaxSize().padding(18.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){item{Text(if(id==null)stringResource(R.string.add) else stringResource(R.string.edit),style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.Bold)};item{Field(name,{name=it},R.string.product_name,attempted&&name.isBlank())};item{Field(brand,{brand=it},R.string.brand)};item{Field(model,{model=it},R.string.model)};item{Field(store,{store=it},R.string.store)};item{Field(price,{price=it},R.string.price,keyboard=KeyboardType.Decimal)};item{Field(purchase,{purchase=it},R.string.purchase_date)};item{Field(months,{months=it},R.string.warranty_months,keyboard=KeyboardType.Number)};item{Field(serial,{serial=it},R.string.serial_number)};item{Field(order,{order=it},R.string.order_number)};item{Field(notes,{notes=it},R.string.notes)};item{Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){OutlinedButton({photoPick.launch(arrayOf("image/*"))}){Icon(Icons.Default.Image,null);Text(stringResource(R.string.choose_photo))};OutlinedButton({invoicePick.launch(arrayOf("image/*","application/pdf"))}){Icon(Icons.Default.Receipt,null);Text(stringResource(R.string.choose_invoice))}}};item{Button({attempted=true;val pd=parseDate(purchase);val m=months.toIntOrNull();if(name.isBlank()||pd==null||m==null)return@Button;val p=ProductEntity(id=existing?.id?:0,name=name.trim(),brand=brand.trim(),model=model.trim(),store=store.trim(),priceCents=((price.replace(',','.').toDoubleOrNull()?:0.0)*100).toLong(),purchaseDate=pd,warrantyMonths=m,warrantyEndDate=WarrantyRepository.calculateEnd(pd,m),serialNumber=serial.trim(),orderNumber=order.trim(),notes=notes.trim(),photoUri=photo,invoiceUri=invoice,createdAt=existing?.createdAt?:System.currentTimeMillis());vm.save(p){saved->WarrantyWorker.schedule(context,saved,p.name,p.warrantyEndDate,setOf(90,30,7,1));done()}},Modifier.fillMaxWidth()){Text(stringResource(R.string.save))}}}}
