@Composable private fun DetailScreen(vm:MainViewModel,id:Long,nav:NavHostController){val item=vm.product(id).collectAsState(initial=null).value?:return;val p=item.product;var confirm by remember{mutableStateOf(false)};LazyColumn(Modifier.fillMaxSize().padding(18.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{if(p.photoUri!=null)AsyncImage(Uri.parse(p.photoUri),null,Modifier.fillMaxWidth().height(220.dp),contentScale=ContentScale.Crop);Text(p.name,style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.Bold);StatusText(p)};item{Info("Marca / modelo",listOf(p.brand,p.model).filter{it.isNotBlank()}.joinToString(" · "));Info(stringResource(R.string.price),money(p.priceCents));Info(stringResource(R.string.store),p.store);Info(stringResource(R.string.purchase_date),date(p.purchaseDate));Info("Fim da garantia",date(p.warrantyEndDate));Info(stringResource(R.string.serial_number),p.serialNumber);Info(stringResource(R.string.order_number),p.orderNumber);Info(stringResource(R.string.notes),p.notes)};item{Button({nav.navigate("problem/$id")},Modifier.fillMaxWidth()){Icon(Icons.Default.Build,null);Text(stringResource(R.string.problem))}};item{Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){OutlinedButton({nav.navigate("edit/$id")},Modifier.weight(1f)){Text(stringResource(R.string.edit))};OutlinedButton({confirm=true},Modifier.weight(1f)){Text(stringResource(R.string.delete))}}};item{Text(stringResource(R.string.repairs),style=MaterialTheme.typography.titleLarge)};items(item.repairs){Text("${date(it.date)} · ${it.status}\n${it.problem}")};item{RepairForm(id,vm)}};if(confirm)AlertDialog({confirm=false},{TextButton({vm.delete(p){nav.navigate("products"){popUpTo("home")}}}){Text(stringResource(R.string.yes))}},dismissButton={TextButton({confirm=false}){Text(stringResource(R.string.no))}},title={Text(stringResource(R.string.confirm_delete))})}
