@Composable private fun RepairForm(id:Long,vm:MainViewModel){var show by remember{mutableStateOf(false)};var problem by remember{mutableStateOf("")};var company by remember{mutableStateOf("")};var status by remember{mutableStateOf("Pedido criado")};if(!show){OutlinedButton({show=true}){Text(stringResource(R.string.add_repair))};return};Column(verticalArrangement=Arrangement.spacedBy(8.dp)){Field(problem,{problem=it},R.string.problem_description);Field(company,{company=it},R.string.company);var expanded by remember{mutableStateOf(false)};Box{OutlinedButton({expanded=true}){Text(status)};DropdownMenu(expanded,{expanded=false}){listOf("Pedido criado","Enviado","Em reparação","Reparado","Substituído","Reembolsado","Encerrado").forEach{DropdownMenuItem({Text(it)},{status=it;expanded=false})}}};Button({if(problem.isNotBlank()){vm.addRepair(RepairEntity(productId=id,date=System.currentTimeMillis(),problem=problem,company=company,status=status));show=false}}){Text(stringResource(R.string.save))}}}

@Composable private fun ProblemScreen(vm:MainViewModel,id:Long){val item=vm.product(id).collectAsState(initial=null).value?:return;var description by remember{mutableStateOf("")};val context=LocalContext.current;Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(18.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){Text(stringResource(R.string.problem),style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.Bold);ProductCard(item){};Field(description,{description=it},R.string.problem_description);Text("O relatório inclui os dados do produto, garantia, loja, números de referência e a lista de documentos. Os ficheiros originais permanecem no dispositivo até escolher partilhá-los.");Button({shareReport(context,item,description)},Modifier.fillMaxWidth()){Icon(Icons.Default.Share,null);Text(stringResource(R.string.generate_report))}}}
private fun shareReport(context:Context,item:ProductWithDetails,description:String){val p=item.product;val dir=File(context.cacheDir,"reports").apply{mkdirs()};val f=File(dir,"WarrantyBox-${p.name.replace(Regex("[^A-Za-z0-9]"),"-")}.txt");f.writeText("WarrantyBox — Relatório de assistência\n\nProduto: ${p.name}\nMarca/modelo: ${p.brand} ${p.model}\nLoja: ${p.store}\nPreço: ${money(p.priceCents)}\nCompra: ${date(p.purchaseDate)}\nGarantia até: ${date(p.warrantyEndDate)}\nN.º série: ${p.serialNumber}\nN.º encomenda: ${p.orderNumber}\n\nProblema:\n$description\n\nNotas:\n${p.notes}");val uri=FileProvider.getUriForFile(context,"${context.packageName}.files",f);context.startActivity(Intent.createChooser(Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION),null))}

@Composable private fun StatsScreen(vm:MainViewModel){
 val items by vm.products.collectAsState();val total by vm.totalSpent.collectAsState();val groups by vm.totals.collectAsState()
 val monthly=items.groupBy{Instant.ofEpochMilli(it.product.purchaseDate).atZone(ZoneId.systemDefault()).toLocalDate().withDayOfMonth(1)}.mapValues{e->e.value.sumOf{it.product.priceCents}}.toList().sortedByDescending{it.first}.take(12).reversed()
 val yearly=items.groupBy{Instant.ofEpochMilli(it.product.purchaseDate).atZone(ZoneId.systemDefault()).year}.mapValues{e->e.value.sumOf{it.product.priceCents}}.toList().sortedByDescending{it.first}
 LazyColumn(Modifier.fillMaxSize().padding(18.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Text(stringResource(R.string.statistics),style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.Bold)};item{Metric(stringResource(R.string.total_spent),money(total),Modifier.fillMaxWidth())};item{Row(horizontalArrangement=Arrangement.spacedBy(10.dp)){Metric(stringResource(R.string.products),items.size.toString(),Modifier.weight(1f));Metric(stringResource(R.string.active_warranties),items.count{it.product.daysRemaining()>=0}.toString(),Modifier.weight(1f))}};item{Text(stringResource(R.string.by_category),style=MaterialTheme.typography.titleLarge)};items(groups){val max=groups.maxOfOrNull{x->x.total}?:1;Column{Row{Text(it.category?:"Outros",Modifier.weight(1f));Text(money(it.total))};LinearProgressIndicator({it.total.toFloat()/max.coerceAtLeast(1)},Modifier.fillMaxWidth())}};item{Text("Compras por mês",style=MaterialTheme.typography.titleLarge)};items(monthly){entry->val max=monthly.maxOfOrNull{it.second}?:1;Column{Row{Text(entry.first.format(DateTimeFormatter.ofPattern("MMM yyyy")),Modifier.weight(1f));Text(money(entry.second))};LinearProgressIndicator({entry.second.toFloat()/max.coerceAtLeast(1)},Modifier.fillMaxWidth())}};item{Text("Totais anuais",style=MaterialTheme.typography.titleLarge)};items(yearly){entry->Row{Text(entry.first.toString(),Modifier.weight(1f));Text(money(entry.second),fontWeight=FontWeight.Bold)}}}
}
